        /// <summary>Ruta por clave ampliada.</summary>
        public static IReadOnlyDictionary<string, RutaDisposicion> Rutas { get; } = Entradas.ToDictionary(e => e.Clave, e => e.Ruta, StringComparer.Ordinal);

        /// <summary>Contexto que necesita el resto del flujo. Ninguna entrada trae código de material: solo orientan.</summary>
        internal static ContextoObjeto Contexto(Entrada e) => e.Ruta switch
        {
            R.Blanca => ContextoObjeto.ResiduoAprovechable,
            R.Verde => ContextoObjeto.ResiduoOrganico,
            R.Negra => e.Sanitario ? ContextoObjeto.ResiduoSanitario : ContextoObjeto.ResiduoNoAprovechable,
            R.Raee => ContextoObjeto.ResiduoElectronico,
            R.PilasBaterias or R.Medicamentos or R.Bombillos or R.Peligroso or R.Cortopunzante or R.AceiteUsado => ContextoObjeto.ResiduoEspecial,
            _ => ContextoObjeto.ObjetoCotidiano,
        };

        /// <summary>Las entradas como objetos del catálogo.</summary>
        internal static IEnumerable<ObjetoConocido> Objetos() => Entradas.Select(e =>
            new ObjetoConocido(e.Clave, e.Frase, Contexto(e), e.Emoji, e.Frase, e.Explicacion ?? MatrizDecisionResiduos.Texto(e.Ruta)));
    }
